    sort.Float64s(sortedNumbers)

    // Check adjacent pairs in the sorted array
    for i := 0; i < len(sortedNumbers)-1; i++ {
        if sortedNumbers[i+1] - sortedNumbers[i] < threshold {
            return true
        }
    }

    return false
}
