package find_closest_elements_test

import (
    "math"
)

func find_closest_elements(numbers []float64) []interface{} {
    if len(numbers) < 2 {
        return nil
    }

    minDiff := math.Inf(1)
    var closestPair [2]float64

    for i := 0; i < len(numbers); i++ {
        for j := i + 1; j < len(numbers); j++ {
            diff := math.Abs(numbers[i] - numbers[j])
            if diff < minDiff {
                minDiff = diff
                if numbers[i] <= numbers[j] {
                    closestPair[0] = numbers[i]
                    closestPair[1] = numbers[j]
                } else {
                    closestPair[0] = numbers[j]
                    closestPair[1] = numbers[i]
                }
            }
        }
    }

    return []interface{}{closestPair[0], closestPair[1]}
}
