// triples_sum_to_zero takes a list of integers as an input.
// it returns true if there are three distinct elements in the list that
// sum to zero, and false otherwise.
// >>> triples_sum_to_zero([]int{1, 3, 5, 0})
// false
// >>> triples_sum_to_zero([]int{1, 3, -2, 1})
// true
// >>> triples_sum_to_zero([]int{1, 2, 3, 7})
// false
// >>> triples_sum_to_zero([]int{2, 4, -5, 3, 9, 7})
// true
// >>> triples_sum_to_zero([]int{1})
// false
func triples_sum_to_zero(l []int) bool {
    n := len(l)
    if n < 3 {
        return false
    }

    // Sort the array to use two-pointer technique
    for i := 0; i < n-1; i++ {
        for j := i + 1; j < n; j++ {
            if l[i] > l[j] {
                l[i], l[j] = l[j], l[i]
            }
        }
    }

    // Use three-pointer approach
    for i := 0; i < n-2; i++ {
        left := i + 1
        right := n - 1

        for left < right {
            sum := l[i] + l[left] + l[right]

            if sum == 0 {
                return true
            } else if sum < 0 {
                left++
            } else {
                right--
            }
        }
    }

    return false
}
