import (
    "sort"
)

func sort_array(arr []int) []int {
    // Create a copy of the array to avoid modifying the original
    result := make([]int, len(arr))
    copy(result, arr)

    // Sort using custom comparator
    sort.Slice(result, func(i, j int) bool {
        // Count number of 1s in binary representation
        onesI := countOnes(result[i])
        onesJ := countOnes(result[j])

        // If number of ones is different, sort by number of ones
        if onesI != onesJ {
            return onesI < onesJ
        }

        // If number of ones is the same, sort by decimal value
        return result[i] < result[j]
    })

    return result
}

// Helper function to count number of 1s in binary representation
func countOnes(n int) int {
    count := 0
    for n > 0 {
        count += n & 1
        n >>= 1
    }
    return count
}
