package is_nested_test

import (
    "testing"
    "fmt"
)

// Create a function that takes a string as input which contains only square brackets.
// The function should return true if and only if there is a valid subsequence of brackets 
// where at least one bracket in the subsequence is nested.
// >>> is_nested("[[]]")
// true
// >>> is_nested("[]]]]]]][[[[[]")
// false
// >>> is_nested("[][]")
// false
// >>> is_nested("[]")
// false
// >>> is_nested("[[][]]")
// true
// >>> is_nested("[[]][[")
// true
func is_nested(myString string) bool {
    // Count of open brackets
    openCount := 0
    // Flag to track if we have nested brackets
    hasNested := false

    for _, char := range myString {
        if char == '[' {
            openCount++
        } else if char == ']' {
            if openCount > 0 {
                openCount--
                // If we have more than one open bracket before closing,
                // it means we have nested brackets
                if openCount > 0 {
                    hasNested = true
                }
            } else {
                // Unmatched closing bracket, invalid sequence
                return false
            }
        }
    }

    return hasNested
}
