func fix_spaces(text string) string {
    // First, replace all spaces with underscores
    result := strings.ReplaceAll(text, " ", "_")

    // Then, find sequences of more than 2 underscores and replace them with "-"
    // We need to be careful about consecutive underscores
    for strings.Contains(result, "__") {
        // Replace sequences of 3 or more underscores with a single dash
        // We'll use a loop to handle multiple consecutive sequences
        for i := 0; i < len(result)-2; i++ {
            if result[i] == '_' && result[i+1] == '_' && result[i+2] == '_' {
                // Replace three consecutive underscores with a single dash
                result = result[:i] + "-" + result[i+3:]
                break
            }
        }
        // If no three consecutive underscores found, break
        if !strings.Contains(result, "__") {
            break
        }
    }

    return result
}
