func simplify(x string, n string) bool {
    // Parse the first fraction x
    partsX := strings.Split(x, "/")
    numX, _ := strconv.Atoi(partsX[0])
    denX, _ := strconv.Atoi(partsX[1])

    // Parse the second fraction n
    partsN := strings.Split(n, "/")
    numN, _ := strconv.Atoi(partsN[0])
    denN, _ := strconv.Atoi(partsN[1])

    // Calculate the product: (numX/denX) * (numN/denN)
    // This gives us: (numX * numN) / (denX * denN)
    numerator := numX * numN
    denominator := denX * denN

    // Check if the result is a whole number
    // A fraction is a whole number if the numerator is divisible by the denominator
    return numerator%denominator == 0
}
