func do_algebra(operator []string, operand []int) int {
    result := operand[0]

    for i := 0; i < len(operator); i++ {
        op := operator[i]
        nextOperand := operand[i+1]

        switch op {
        case "+":
            result += nextOperand
        case "-":
            result -= nextOperand
        case "*":
            result *= nextOperand
        case "//":
            result /= nextOperand
        case "**":
            result = pow(result, nextOperand)
        }
    }

    return result
}

func pow(base, exp int) int {
    result := 1
    for i := 0; i < exp; i++ {
        result *= base
    }
    return result
