    // Sum = 1.5+0.5+0.5+1.5 = 4.0
    // MAD = 4.0 / 4 = 1.0
    if got := mean_absolute_deviation([]float64{1.0, 2.0, 3.0, 4.0}); !reflect.DeepEqual(got, 1.0) {
