    // MAD = 0 / 1 = 0.0
    if got := mean_absolute_deviation([]float64{5.0}); !reflect.DeepEqual(got, 0.0) {
        panic(fmt.Sprintf("Expected 0.0, got %v", got))
    }

    // Test case 3: [1.0, 1.0, 1.0]
