// For a given number n, find the largest number that divides n evenly, smaller than n
// >>> largest_divisor(15)
// 5
func largest_divisor(n int) int {
    // Start from n-1 and work downwards to find the largest divisor
    for i := n - 1; i >= 1; i-- {
        if n%i == 0 {
            return i
        }
    }
    return 1 // This case only occurs if n == 1, but by definition, 1 has no proper divisor smaller than itself
}
