package fizz_buzz_test

import (
    "reflect"
    "testing"
)

// Return the number of times the digit 7 appears in integers less than n which are divisible by 11 or 13.
// >>> fizz_buzz(50)
// 0
// >>> fizz_buzz(78)
// 2
// >>> fizz_buzz(79)
// 3
func fizz_buzz(n int) int {
    count := 0
    for i := 1; i < n; i++ {
        if i%11 == 0 || i%13 == 0 {
            // Count occurrences of digit '7' in i
            num := i
            for num > 0 {
                if num%10 == 7 {
                    count++
                }
                num /= 10
            }
        }
    }
    return count
}
```

