package change_base_test

import (
    "reflect"
    "strconv"
)

func change_base(x int, base int) string {
    if x == 0 {
        return "0"
    }
    var digits []string
    for x > 0 {
        digits = append(digits, strconv.Itoa(x%base))
        x /= base
    }
    // Reverse the digits
    for i, j := 0, len(digits)-1; i < j; i, j = i+1, j-1 {
        digits[i], digits[j] = digits[j], digits[i]
    }
    return joinStrings(digits)
}

func joinStrings(s []string) string {
    result := ""
    for _, str := range s {
        result += str
    }
    return result
}
