package is_palindrome_test

import (
    "reflect"
)

// Checks if given string is a palindrome
// >>> is_palindrome("")
// true
// >>> is_palindrome("aba")
// true
// >>> is_palindrome("aaaaa")
// true
// >>> is_palindrome("zbcd")
// false
func is_palindrome(text string) bool {
    // Convert to lowercase to handle case-insensitive comparison
    text = text
    // Use two pointers from start and end
    left := 0
    right := len(text) - 1

    for left < right {
        if text[left] != text[right] {
            return false
        }
        left++
        right--
    }
    return true
}
