package pluck_test

import (
    "reflect"
)

func pluck(arr []int) []int {
    if len(arr) == 0 {
        return []int{}
    }

    smallestEven := -1
    smallestIndex := -1

    for i, val := range arr {
        if val%2 == 0 {
            if smallestEven == -1 || val < smallestEven || (val == smallestEven && i < smallestIndex) {
                smallestEven = val
                smallestIndex = i
            }
        }
    }

    if smallestEven == -1 {
        return []int{}
    }

    return []int{smallestEven, smallestIndex}
}
