package will_it_fly_test

import (
    "reflect"
)

func will_it_fly(q []int, w int) bool {
    // Check if the list is palindromic (balanced)
    isBalanced := true
    for i := 0; i < len(q)/2; i++ {
        if q[i] != q[len(q)-1-i] {
            isBalanced = false
            break
        }
    }

    // Calculate the sum of elements
    sum := 0
    for _, val := range q {
        sum += val
    }

    // The object flies if it's balanced and the sum is <= w
    return isBalanced && sum <= w
}
