import (
    "reflect"
)

func count_up_to(n int) []int {
    if n <= 2 {
        return []int{}
    }

    primes := []int{}
    for i := 2; i < n; i++ {
        if isPrime(i) {
            primes = append(primes, i)
        }
    }
    return primes
}

func isPrime(num int) bool {
    if num < 2 {
        return false
    }
    for i := 2; i*i <= num; i++ {
        if num%i == 0 {
            return false
        }
    }
    return true
}
