func make_a_pile(n int) []int {
    result := make([]int, n)
    current := n
    result[0] = current

    for i := 1; i < n; i++ {
        if n%2 == 1 { // n is odd
            current += 2 // next odd number
        } else { // n is even
            current += 2 // next even number
        }
        result[i] = current
    }

    return result
