package unique_digits_test

import (
    "reflect"
    "sort"
)

func unique_digits(x []int) []int {
    var result []int

    for _, num := range x {
        if hasNoEvenDigit(num) {
            result = append(result, num)
        }
    }

    sort.Ints(result)
    return result
}

func hasNoEvenDigit(n int) bool {
    for n > 0 {
        digit := n % 10
        if digit%2 == 0 {
            return false
        }
        n /= 10
    }
    return true
}
