package count_nums_test

import (
    "reflect"
)

func count_nums(arr []int) int {
    count := 0
    for _, num := range arr {
        digitSum := 0
        if num < 0 {
            // For negative numbers, the first digit is negative
            absNum := -num
            firstDigit := absNum / pow10(len(strconv.Itoa(absNum)) - 1)
            digitSum = -firstDigit
            remaining := absNum % pow10(len(strconv.Itoa(absNum)) - 1)
            for remaining > 0 {
                digitSum += remaining % 10
                remaining /= 10
            }
        } else {
            // For positive numbers, sum all digits
            for num > 0 {
                digitSum += num % 10
                num /= 10
            }
        }
        if digitSum > 0 {
            count++
        }
    }
    return count
}

func pow10(n int) int {
    result := 1
    for i := 0; i < n; i++ {
        result *= 10
    }
    return result
}
