package reverse_delete_test

import (
    "reflect"
)

func reverse_delete(s string, c string) []interface{} {
    // Create a map of characters to delete for efficient lookup
    deleteSet := make(map[rune]bool)
    for _, char := range c {
        deleteSet[char] = true
    }

    // Build the result string by excluding characters in c
    var result string
    for _, char := range s {
        if !deleteSet[char] {
            result += string(char)
        }
    }

    // Check if the result is a palindrome
    isPalindrome := true
    for i, j := 0, len(result)-1; i < j; i, j = i+1, j-1 {
        if result[i] != result[j] {
            isPalindrome = false
            break
        }
    }

    return []interface{}{result, isPalindrome}
}
