package sort_array_test

import (
    "reflect"
    "sort"
)

func sort_array(arr []int) []int {
    // Create a slice of pairs (value, count of ones in binary)
    pairs := make([]struct {
        value    int
        onesCount int
    }, len(arr))

    // Count the number of ones in binary representation for each number
    for i, num := range arr {
        onesCount := 0
        n := num
        for n > 0 {
            onesCount += n & 1
            n >>= 1
        }
        pairs[i] = struct {
            value    int
            onesCount int
        }{value: num, onesCount: onesCount}
    }

    // Sort by ones count first, then by value
    sort.Slice(pairs, func(i, j int) bool {
        if pairs[i].onesCount != pairs[j].onesCount {
            return pairs[i].onesCount < pairs[j].onesCount
        }
        return pairs[i].value < pairs[j].value
    })

    // Extract the sorted values
    result := make([]int, len(arr))
    for i, pair := range pairs {
        result[i] = pair.value
    }

    return result
}
