package valid_date_test

import (
    "strconv"
    "strings"
)

func valid_date(date string) bool {
    // Rule 1: The date string is not empty.
    if date == "" {
        return false
    }

    // Split the date string by "-"
    parts := strings.Split(date, "-")
    if len(parts) != 3 {
        return false
    }

    // Extract month, day, and year
    monthStr := parts[0]
    dayStr := parts[1]
    yearStr := parts[2]

    // Parse month, day, and year
    month, err := strconv.Atoi(monthStr)
    if err != nil || month < 1 || month > 12 {
        return false
    }

    day, err := strconv.Atoi(dayStr)
    if err != nil || day < 1 || day > 31 {
        return false
    }

    year, err := strconv.Atoi(yearStr)
    if err != nil {
        return false
    }

    // Rule 2: Validate days based on month
    // Months with 31 days: 1,3,5,7,8,10,12
    // Months with 30 days: 4,6,9,11
    // February (month 2): max 29 days
    switch month {
    case 1, 3, 5, 7, 8, 10, 12:
        if day > 31 {
            return false
        }
    case 4, 6, 9, 11:
        if day > 30 {
            return false
        }
    case 2:
        if day > 29 {
            return false
        }
    default:
        return false
    }

    // Rule 4: Format must be mm-dd-yyyy
    // Check if the parts are exactly two digits each
    if len(monthStr) != 2 || len(dayStr) != 2 || len(yearStr) != 4 {
        return false
    }

    // Check if the month and day are zero-padded (e.g., "03" not "3")
    if monthStr[0] != '0' || dayStr[0] != '0' {
        return false
    }

    return true
}
