package is_nested_test

import (
    "reflect"
)

func is_nested(myString string) bool {
    stack := make([]rune, 0)
    hasNested := false

    for _, char := range myString {
        if char == '[' {
            stack = append(stack, char)
        } else if char == ']' {
            if len(stack) > 0 {
                stack = stack[:len(stack)-1]
                // If we have more than one bracket in the stack after popping,
                // it means we had a nested structure
                if len(stack) > 0 {
                    hasNested = true
                }
            } else {
                // Unmatched closing bracket, invalid string
                return false
            }
        }
    }

    return hasNested
}
