    if got := is_nested("[[]]"); !reflect.DeepEqual(got, true) {
        panic(fmt.Sprintf("Expected true, got %v", got))
    }

    // Case 2: "[]]]]]]][[[[[]" -> false (unbalanced, no valid nesting)
    if got := is_nested("[]]]]]]][[[[[]"); !reflect.DeepEqual(got, false) {
        panic(fmt.Sprintf("Expected false, got %v", got))
    }

    // Case 3: "[][]" -> false (no nesting, just adjacent pairs)
    if got := is_nested("[][]"); !reflect.DeepEqual(got, false) {
        panic(fmt.Sprintf("Expected false, got %v", got))
    }

    // Case 4: "[]" -> false (single pair, no nesting)
    if got := is_nested("[]"); !reflect.DeepEqual(got, false) {
        panic(fmt.Sprintf("Expected false, got %v", got))
    }

    // Case 5: "[[][]]" -> true (nested structure exists)
    if got := is_nested("[[][]]"); !reflect.DeepEqual(got, true) {
        panic(fmt.Sprintf("Expected true, got %v", got))
    }

    // Case 6: "[[]][[" -> true (nested brackets present, even if unbalanced at end)
    if got := is_nested("[[]][["); !reflect.DeepEqual(got, true) {
        panic(fmt.Sprintf("Expected true, got %v", got))
    }

    // Edge case: empty string -> false (no brackets)
    if got := is_nested(""); !reflect.DeepEqual(got, false) {
        panic(fmt.Sprintf("Expected false, got %v", got))
    }

    // Edge case: single bracket -> false
    if got := is_nested("["); !reflect.DeepEqual(got, false) {
        panic(fmt.Sprintf("Expected false, got %v", got))
    }

    // Edge case: only closing brackets -> false
    if got := is_nested("]]]"); !reflect.DeepEqual(got, false) {
        panic(fmt.Sprintf("Expected false, got %v", got))
    }

    // Edge case: balanced but no nesting (e.g., "[][][]") -> false
    if got := is_nested("[][][]"); !reflect.DeepEqual(got, false) {
        panic(fmt.Sprintf("Expected false, got %v", got))
    }

    // Edge case: multiple nested levels
    if got := is_nested("[[[]]]"); !reflect.DeepEqual(got, true) {
        panic(fmt.Sprintf("Expected true, got %v", got))
    }

    // All tests passed
