package fix_spaces_test

import (
    "reflect"
    "strings"
)

func fix_spaces(text string) string {
    // Trim leading and trailing spaces
    text = strings.TrimSpace(text)

    // Replace all spaces with underscores first
    result := strings.ReplaceAll(text, " ", "_")

    // Now, replace sequences of more than 2 underscores with a single dash
    // We need to detect sequences of 3 or more underscores
    // We'll use a loop to find consecutive underscores
    for {
        // Find the first occurrence of 3 or more consecutive underscores
        i := 0
        for i < len(result) {
            if i+2 < len(result) && result[i] == '_' && result[i+1] == '_' && result[i+2] == '_' {
                // Found 3 or more underscores, replace the first 3 with a single dash
                result = result[:i] + "-" + result[i+3:]
                break
            }
            i++
        }
        if i >= len(result) {
            break
        }
    }

    return result
}
