package simplify_test

import (
    "strconv"
    "strings"
)

func simplify(x string, n string) bool {
    // Parse x
    partsX := strings.Split(x, "/")
    numX, _ := strconv.Atoi(partsX[0])
    denX, _ := strconv.Atoi(partsX[1])

    // Parse n
    partsN := strings.Split(n, "/")
    numN, _ := strconv.Atoi(partsN[0])
    denN, _ := strconv.Atoi(partsN[1])

    // Compute x * n = (numX/denX) * (numN/denN) = (numX * numN) / (denX * denN)
    numerator := numX * numN
    denominator := denX * denN

    // Check if the result is a whole number: numerator must be divisible by denominator
    return numerator%denominator == 0
}
