package do_algebra_test

import (
    "reflect"
)

func do_algebra(operator []string, operand []int) int {
    if len(operator) == 0 || len(operand) == 0 {
        panic("operator and operand must not be empty")
    }
    if len(operator) != len(operand)-1 {
        panic("operator length must be one less than operand length")
    }

    // Start with the first operand
    result := operand[0]

    // Apply each operation in sequence
    for i := 0; i < len(operator); i++ {
        op := operator[i]
        nextOperand := operand[i+1]

        switch op {
        case "+":
            result += nextOperand
        case "-":
            result -= nextOperand
        case "*":
            result *= nextOperand
        case "//":
            if nextOperand == 0 {
                panic("division by zero")
            }
            result /= nextOperand
        case "**":
            result = pow(result, nextOperand)
        default:
            panic("unknown operator: " + op)
        }
    }

    return result
}

func pow(base, exp int) int {
    if exp == 0 {
        return 1
    }
    result := base
    for i := 1; i < exp; i++ {
        result *= base
    }
    return result
}
