use std::f64::EPSILON;

fn find_closest_elements(numbers: Vec<f64>) -> (f64, f64) {
    let mut min_diff = f64::INFINITY;
    let mut closest_pair = (0.0, 0.0);

    for i in 0..numbers.len() {
        for j in (i + 1)..numbers.len() {
            let diff = (numbers[i] - numbers[j]).abs();
            if diff < min_diff {
                min_diff = diff;
                // Ensure smaller number comes first
                if numbers[i] <= numbers[j] {
                    closest_pair = (numbers[i], numbers[j]);
                } else {
                    closest_pair = (numbers[j], numbers[i]);
                }
            }
        }
    }

    closest_pair
}
