use std::collections::HashMap;

fn triples_sum_to_zero(l: Vec<isize>) -> bool {
    let n = l.len();
    if n < 3 {
        return false;
    }

    // Use a hash map to store indices of values
    let mut value_to_indices = HashMap::new();
    for (i, &val) in l.iter().enumerate() {
        value_to_indices.insert(val, i);
    }

