use std::str::FromStr;

fn valid_date(date: String) -> bool {
    // Check if the date string is empty
    if date.is_empty() {
        return false;
    }

    // Split the date string by '-' to get month, day, and year
    let parts: Vec<&str> = date.split('-').collect();

    // Check if there are exactly 3 parts
    if parts.len() != 3 {
        return false;
    }

    // Parse month, day, and year
    let month_str = parts[0];
    let day_str = parts[1];
    let year_str = parts[2];

    // Check if all parts are valid numbers
    let month = match month_str.parse::<u8>() {
        Ok(m) => m,
        Err(_) => return false,
    };

    let day = match day_str.parse::<u8>() {
        Ok(d) => d,
        Err(_) => return false,
    };

    let year = match year_str.parse::<u32>() {
        Ok(y) => y,
        Err(_) => return false,
    };

    // Check if month is valid
    if month < 1 || month > 12 {
        return false;
    }

    // Check if day is valid based on month
    let max_days = match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => 29,
        _ => return false,
    };

    if day < 1 || day > max_days {
        return false;
    }

    // Check if the date format is mm-dd-yyyy (no leading zeros allowed for month/day)
    if month_str.len() != 2 || day_str.len() != 2 || year_str.len() != 4 {
        return false;
    }

    // Check if the date format uses '-' as separator
    if date.chars().nth(2).unwrap() != '-' || date.chars().nth(5).unwrap() != '-' {
        return false;
    }

    true
}
