fn is_nested(string: String) -> bool {
    let mut stack = Vec::new();
    let mut has_nested = false;

    for c in string.chars() {
        if c == '[' {
            stack.push(c);
        } else if c == ']' {
            if stack.is_empty() {
                // Unmatched closing bracket, but we don't return false immediately
                // because we're looking for nested subsequence
                continue;
            }

            // Pop the matching opening bracket
            stack.pop();

            // If there are still brackets in the stack, we had nesting
            if !stack.is_empty() {
                has_nested = true;
            }
        }
    }

    has_nested
}
