fn simplify(x: String, n: String) -> bool {
    // Parse the first fraction x
    let x_parts: Vec<&str> = x.split('/').collect();
    let x_numerator = i32::from_str(x_parts[0]).unwrap();
    let x_denominator = i32::from_str(x_parts[1]).unwrap();

    // Parse the second fraction n
    let n_parts: Vec<&str> = n.split('/').collect();
    let n_numerator = i32::from_str(n_parts[0]).unwrap();
    let n_denominator = i32::from_str(n_parts[1]).unwrap();

    // Calculate the product: (x_numerator / x_denominator) * (n_numerator / n_denominator)
    // This gives: (x_numerator * n_numerator) / (x_denominator * n_denominator)
    let numerator = x_numerator * n_numerator;
    let denominator = x_denominator * n_denominator;

    // Check if the result is a whole number (i.e., denominator divides numerator evenly)
    numerator % denominator == 0
}
