fn main() {
    // Test case 1: [1.0, 2.0, 3.0, 4.0]
    // Mean = (1+2+3+4)/4 = 2.5
    // Absolute differences: |1-2.5|=1.5, |2-2.5|=0.5, |3-2.5|=0.5, |4-2.5|=1.5
    // Sum = 1.5+0.5+0.5+1.5 = 4.0
    // MAD = 4.0 / 4 = 1.0
    assert_eq!(mean_absolute_deviation(vec![1.0, 2.0, 3.0, 4.0]), 1.0);

    // Test case 2: [5.0]
    // Mean = 5.0
    // Absolute difference: |5-5| = 0.0
    // MAD = 0.0 / 1 = 0.0
    assert_eq!(mean_absolute_deviation(vec![5.0]), 0.0);

    // Test case 3: [1.0, 1.0, 1.0]
    // Mean = 1.0
    // Absolute differences: 0.0, 0.0, 0.0
    // MAD = 0.0 / 3 = 0.0
    assert_eq!(mean_absolute_deviation(vec![1.0, 1.0, 1.0]), 0.0);

    // Test case 4: [2.0, 4.0]
    // Mean = (2+4)/2 = 3.0
    // Absolute differences: |2-3|=1.0, |4-3|=1.0
    // Sum = 2.0, MAD = 2.0 / 2 = 1.0
    assert_eq!(mean_absolute_deviation(vec![2.0, 4.0]), 1.0);

    // Test case 5: Empty vector
    // By definition, MAD of empty set is 0.0
    assert_eq!(mean_absolute_deviation(vec![]), 0.0);

    // Test case 6: [0.0, 6.0]
    // Mean = 3.0
    // Absolute differences: |0-3|=3.0, |6-3|=3.0
    // Sum = 6.0, MAD = 6.0 / 2 = 3.0
    assert_eq!(mean_absolute_deviation(vec![0.0, 6.0]), 3.0);
