/// For a given number n, find the largest number that divides n evenly, smaller than n
/// >>> largest_divisor(15)
/// 5
fn largest_divisor(n: isize) -> isize {
    if n <= 1 {
        panic!("Input must be greater than 1");
    }

    // Start from n-1 and work downwards to find the largest divisor
    for i in (1..n).rev() {
        if n % i == 0 {
            return i;
        }
    }

    // This should never be reached for n > 1
    panic!("No divisor found");
}
