use std::collections::HashMap;

fn triples_sum_to_zero(l: Vec<isize>) -> bool {
    let n = l.len();
    if n < 3 {
        return false;
    }

    // Use a hash map to store indices of elements
    let mut index_map: HashMap<isize, usize> = HashMap::new();
    for (i, &val) in l.iter().enumerate() {
        index_map.insert(val, i);
    }

    // Check all possible pairs
    for i in 0..n {
        for j in (i + 1)..n {
            let a = l[i];
            let b = l[j];
            let c = -a - b; // We want a + b + c = 0

            // Check if c exists in the array and is distinct from a and b
            if let Some(k) = index_map.get(&c) {
                if k != i && k != j {
                    return true;
                }
            }
        }
    }

    false
}
```

