    // Test case 1: [1, 3, 5, 0] → no three elements sum to zero
    assert_eq!(triples_sum_to_zero(vec![1, 3, 5, 0]), false);

    // Test case 2: [1, 3, -2, 1] → 1 + 3 + (-2) = 2 ≠ 0, but 1 + (-2) + 1 = 0 → true
    // Actually: 1 + (-2) + 1 = 0 → valid triple (1, -2, 1) → true
    assert_eq!(triples_sum_to_zero(vec![1, 3, -2, 1]), true);

    // Test case 3: [1, 2, 3, 7] → all positive, no combination sums to zero
    assert_eq!(triples_sum_to_zero(vec![1, 2, 3, 7]), false);

    // Test case 4: [2, 4, -5, 3, 9, 7] → 2 + 4 + (-5) = 1 ≠ 0, but 2 + 3 + (-5) = 0 → true
    assert_eq!(triples_sum_to_zero(vec![2, 4, -5, 3, 9, 7]), true);

    // Test case 5: [1] → too few elements
    assert_eq!(triples_sum_to_zero(vec![1]), false);

    // Test case 6: [0, 0, 0] → 0 + 0 + 0 = 0 → true
    assert_eq!(triples_sum_to_zero(vec![0, 0, 0]), true);

    // Test case 7: [-1, 1, 0] → -1 + 1 + 0 = 0 → true
    assert_eq!(triples_sum_to_zero(vec![-1, 1, 0]), true);

    // Test case 8: [1, 2, -3] → 1 + 2 + (-3) = 0 → true
    assert_eq!(triples_sum_to_zero(vec![1, 2, -3]), true);

    // Test case 9: [1, 2, 3] → all positive, no sum to zero
    assert_eq!(triples_sum_to_zero(vec![1, 2, 3]), false);
