fn change_base(x: isize, base: isize) -> String {
    if x == 0 {
        return String::from("0");
    }
    let mut n = x;
    let mut result = String::new();
    while n > 0 {
        let remainder = n % base;
        result = format!("{}{}", remainder, result);
        n /= base;
    }
    result
}
