fn correct_bracketing(brackets: String) -> bool {
    let mut stack = 0;
    for c in brackets.chars() {
        match c {
            '<' => stack += 1,
            '>' => {
                if stack == 0 {
                    return false; // No matching opening bracket
                }
                stack -= 1;
            },
            _ => return false, // Invalid character
        }
    }
    stack == 0 // All brackets must be matched
}
```

