    assert_eq!(correct_bracketing(String::from("<<><>>")), true);
    assert_eq!(correct_bracketing(String::from("><<>")), false);
    assert_eq!(correct_bracketing(String::from("")), true); // Edge case: empty string
    assert_eq!(correct_bracketing(String::from("<<<>>>")), true);
    assert_eq!(correct_bracketing(String::from("<<>>")), true);
    assert_eq!(correct_bracketing(String::from("><")), false);
