fn pluck(arr: Vec<isize>) -> Vec<isize> {
    if arr.is_empty() {
        return Vec::new();
    }

    let mut smallest_even = None;
    let mut smallest_index = None;

    for (index, &value) in arr.iter().enumerate() {
        if value % 2 == 0 {
            if smallest_even.is_none() || value < smallest_even.unwrap() {
                smallest_even = Some(value);
                smallest_index = Some(index);
            } else if value == smallest_even.unwrap() && smallest_index.is_none() {
                // This case is redundant since we already set smallest_index when we first see the value
                // But we can still handle it if needed
                smallest_index = Some(index);
            }
        }
    }

    match smallest_even {
        Some(value) => vec![value, smallest_index.unwrap() as isize],
        None => Vec::new(),
    }
}
```

