    assert_eq!(pluck(vec![4, 2, 3]), vec![2, 1]);

    // Example 2: [1, 2, 3] -> smallest even is 2 at index 1
    assert_eq!(pluck(vec![1, 2, 3]), vec![2, 1]);

    // Example 3: [] -> empty vector
    assert_eq!(pluck(vec![]), Vec::<isize>::new());

    // Example 4: [5, 0, 3, 0, 4, 2] -> smallest even is 0, first occurrence at index 1
    assert_eq!(pluck(vec![5, 0, 3, 0, 4, 2]), vec![0, 1]);

    // Edge case: only one even number
    assert_eq!(pluck(vec![7, 8]), vec![8, 1]);

    // Edge case: all odd numbers
    assert_eq!(pluck(vec![1, 3, 5]), Vec::<isize>::new());

    // Edge case: multiple zeros
    assert_eq!(pluck(vec![0, 0, 1]), vec![0, 0]);

    // Edge case: single element even
    assert_eq!(pluck(vec![6]), vec![6, 0]);

    // Edge case: single element odd
    assert_eq!(pluck(vec![7]), Vec::<isize>::new());
}
