fn will_it_fly(q: Vec<isize>, w: isize) -> bool {
    // Check if the vector is palindromic (balanced)
    let is_balanced = q.iter().eq(q.iter().rev());

    // Check if the sum of elements is less than or equal to the maximum weight
    let sum = q.iter().sum::<isize>();
    let within_weight = sum <= w;

    is_balanced && within_weight
}
