    assert_eq!(is_simple_power(2, 2), true); // 2^1 = 2
    assert_eq!(is_simple_power(8, 2), true); // 2^3 = 8
    assert_eq!(is_simple_power(3, 2), false); // No integer power of 2 equals 3
    assert_eq!(is_simple_power(3, 1), false); // 1^k is always 1, never 3
    assert_eq!(is_simple_power(5, 3), false); // No integer power of 3 equals 5
    assert_eq!(is_simple_power(1, 1), true); // 1^0 = 1
    assert_eq!(is_simple_power(16, 4), true); // 4^2 = 16
    assert_eq!(is_simple_power(100, 10), true); // 10^2 = 100
    assert_eq!(is_simple_power(10, 10), true); // 10^1 = 10
    assert_eq!(is_simple_power(0, 2), false); // 0 is not a positive power of 2
}
