use std::fmt::Write;

fn solve(N: isize) -> String {
    if N <= 0 {
        return "0".to_string();
    }

    let mut sum = 0;
    let mut n = N;

    while n > 0 {
        sum += n % 10;
        n /= 10;
    }

    let mut result = String::new();
    let mut num = sum;

    if num == 0 {
        return "0".to_string();
    }

    while num > 0 {
        result.insert(0, if num % 2 == 0 { '0' } else { '1' });
        num /= 2;
    }

    result
}
```

