use std::vec::Vec;

fn sort_array(array: Vec<isize>) -> Vec<isize> {
    if array.is_empty() {
        return Vec::new();
    }

    let first = array[0];
    let last = array[array.len() - 1];
    let sum = first + last;

    let mut result = array.clone();

    if sum % 2 == 1 {
        // Odd sum: sort in ascending order
        result.sort();
    } else {
        // Even sum: sort in descending order
        result.sort_by(|a, b| b.cmp(a));
    }

    result
}
```

