use std::collections::HashSet;

fn count_up_to(n: isize) -> Vec<isize> {
    if n <= 2 {
        return Vec::new();
    }

    let mut primes = Vec::new();
    let mut is_prime = vec![true; n as usize + 1];
    is_prime[0] = false;
    is_prime[1] = false;

    for i in 2..n as usize {
        if is_prime[i] {
            primes.push(i as isize);
            let mut j = i * i;
            while j < n as usize {
                is_prime[j] = false;
                j += i;
            }
        }
    }

    primes
}
```

