fn make_a_pile(n: isize) -> Vec<isize> {
    let mut result = Vec::new();
    let mut current = n;

    for _ in 0..n {
        result.push(current);
        if n % 2 == 1 {
            // n is odd, so next odd number
            current += 2;
        } else {
            // n is even, so next even number
            current += 2;
        }
    }

    result
}
