use std::collections::HashSet;

fn unique_digits(x: Vec<isize>) -> Vec<isize> {
    let mut result = Vec::new();

    for num in x {
        let mut has_even_digit = false;
        let mut temp = num;

        // Extract digits and check if any digit is even
        while temp > 0 {
            let digit = temp % 10;
            if digit % 2 == 0 {
                has_even_digit = true;
                break;
            }
            temp /= 10;
        }

        // If no even digit found, add to result
        if !has_even_digit {
            result.push(num);
        }
    }

    // Sort in increasing order
    result.sort();
    result
}
