fn count_nums(arr: Vec<isize>) -> isize {
    let mut count = 0;
    for num in arr {
        let mut sum_digits = 0;
        let mut n = num;
        while n != 0 {
            sum_digits += n % 10;
            n /= 10;
        }
        if sum_digits > 0 {
            count += 1;
        }
    }
    count
}
