fn sort_array(arr: Vec<isize>) -> Vec<isize> {
    let mut sorted = arr.clone();
    sorted.sort_by(|a, b| {
        let ones_a = a.count_ones();
        let ones_b = b.count_ones();
        match ones_a.cmp(&ones_b) {
            Ordering::Equal => a.cmp(b),
            other => other,
        }
    });
    sorted
}
