use std::str::FromStr;

fn valid_date(date: String) -> bool {
    // Check if the date string is empty
    if date.is_empty() {
        return false;
    }

    // Split the date string by '-' to get components
    let parts: Vec<&str> = date.split('-').collect();
    if parts.len() != 3 {
        return false;
    }

    let month_str = parts[0];
    let day_str = parts[1];
    let year_str = parts[2];

    // Parse month, day, and year
    let month = match month_str.parse::<u8>() {
        Ok(m) => m,
        Err(_) => return false,
    };

    let day = match day_str.parse::<u8>() {
        Ok(d) => d,
        Err(_) => return false,
    };

    let year = match year_str.parse::<u32>() {
        Ok(y) => y,
        Err(_) => return false,
    };

    // Check month range
    if month < 1 || month > 12 {
        return false;
    }

    // Check day range based on month
    let max_days = match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => 29, // February can have up to 29 days (leap year or not)
        _ => return false,
    };

    if day < 1 || day > max_days {
        return false;
    }

    true
}
```

