    assert_eq!(valid_date(String::from("15-01-2012")), false); // Invalid month (15)
    assert_eq!(valid_date(String::from("04-0-2040")), false); // Invalid day (0)
    assert_eq!(valid_date(String::from("06-04-2020")), true); // Valid date
    assert_eq!(valid_date(String::from("06/04/2020")), false); // Wrong separator
    assert_eq!(valid_date(String::from("02-30-2020")), false); // February can't have 30 days
    assert_eq!(valid_date(String::from("02-29-2020")), true); // February 29 is valid (leap year)
    assert_eq!(valid_date(String::from("04-31-2020")), false); // April has 30 days
    assert_eq!(valid_date(String::from("12-31-2020")), true); // December 31 is valid
    assert_eq!(valid_date(String::from("01-01-0000")), true); // Year 0000 is valid
    assert_eq!(valid_date(String::from("")), false); // Empty string
    assert_eq!(valid_date(String::from("01-01-")), false); // Incomplete year
    assert_eq!(valid_date(String::from("01-01-2020")), true); // Valid date
}
