use std::ops::Mul;

/// You are given a vector arr of integers and you need to return
/// sum of magnitudes of integers multiplied by product of all signs
/// of each number in the vector, represented by 1, -1 or 0.
/// Note: return None for empty arr.
/// Example:
/// >>> prod_signs(vec![1, 2, 2, -4])
/// Some(9)
/// >>> prod_signs(vec![0, 1])
/// Some(0)
/// >>> prod_signs(vec![])
/// None
fn prod_signs(arr: Vec<isize>) -> Option<isize> {
    if arr.is_empty() {
        return None;
    }

    let mut sign_product = 1;
    let mut magnitude_sum = 0;

    for num in &arr {
        if *num > 0 {
            sign_product *= 1;
        } else if *num < 0 {
            sign_product *= -1;
        } else {
            sign_product *= 0;
        }
        magnitude_sum += num.abs();
    }

    Some(magnitude_sum * sign_product)
}
