fn is_nested(string: String) -> bool {
    let mut stack = Vec::new();
    let mut has_nested = false;

    for c in string.chars() {
        if c == '[' {
            stack.push(c);
        } else if c == ']' {
            if stack.is_empty() {
                // Unmatched closing bracket, invalid sequence
                return false;
            }
            stack.pop();
            // If we had more than one bracket in the stack before popping,
            // then we had a nested bracket
            if stack.len() >= 1 {
                has_nested = true;
            }
        }
    }

    has_nested
}
```

