    assert_eq!(is_nested(String::from("[]")), false);
    assert_eq!(is_nested(String::from("[[][]]")), true);
    assert_eq!(is_nested(String::from("[[]][[")), true);
    assert_eq!(is_nested(String::from("")), false); // Edge case: empty string
    assert_eq!(is_nested(String::from("[[[]]]")), true); // Nested deeper
    assert_eq!(is_nested(String::from("[][][]")), false); // No nesting, just sequential
