use std::iter::Peekable;

fn fix_spaces(text: String) -> String {
    let mut result = String::new();
    let mut chars = text.chars().peekable();

    while let Some(c) = chars.next() {
        if c == ' ' {
            let mut space_count = 1;
            while let Some(&next) = chars.peek() {
                if next == ' ' {
                    chars.next();
                    space_count += 1;
                } else {
                    break;
                }
            }

            if space_count > 2 {
                result.push_str("-");
            } else {
                result.push('_');
            }
        } else {
            result.push(c);
        }
    }

    result
}
