use std::str::FromStr;

fn simplify(x: String, n: String) -> bool {
    // Parse the fractions
    let x_parts: Vec<&str> = x.split('/').collect();
    let n_parts: Vec<&str> = n.split('/').collect();

    let x_num = x_parts[0].parse::<i64>().unwrap();
    let x_den = x_parts[1].parse::<i64>().unwrap();
    let n_num = n_parts[0].parse::<i64>().unwrap();
    let n_den = n_parts[1].parse::<i64>().unwrap();

    // Compute x * n = (x_num / x_den) * (n_num / n_den)
    // = (x_num * n_num) / (x_den * n_den)
    let numerator = x_num * n_num;
    let denominator = x_den * n_den;

    // Check if the result is a whole number
    // i.e., if numerator is divisible by denominator
    numerator % denominator == 0
}
