function count_nums(arr: number[]): number {
    let count = 0;

    for (const num of arr) {
        let digitSum = 0;
        let absNum = Math.abs(num);
        let isNegative = num < 0;

        // Handle the sign of the first digit
        if (isNegative) {
            digitSum = -1 * (absNum / Math.pow(10, Math.floor(Math.log10(absNum)) + 1));
        }

        // Extract digits
        while (absNum > 0) {
            digitSum += absNum % 10;
            absNum = Math.floor(absNum / 10);
        }

        // For negative numbers, the first digit is negative
        if (isNegative) {
            // Reconstruct the first digit as negative
            const firstDigit = Math.floor(Math.abs(num) / Math.pow(10, Math.floor(Math.log10(Math.abs(num))) + 1));
            digitSum = -firstDigit + (digitSum - firstDigit);
        }

        if (digitSum > 0) {
            count++;
        }
    }

    return count;
}
