function is_nested(string: string): boolean {
    let stack: number[] = [];
    let hasNested = false;

    for (let i = 0; i < string.length; i++) {
        const char = string[i];

        if (char === '[') {
            stack.push(i);
        } else if (char === ']') {
            if (stack.length > 0) {
                const openIndex = stack.pop();
                // If we have a bracket that was opened earlier and now closed,
                // check if there's at least one bracket between the open and close
                if (i - openIndex > 1) {
                    hasNested = true;
                }
            }
        }
    }

    return hasNested;
}
