function simplify(x: string, n: string): boolean {
    // Parse the fractions
    const [num1, den1] = x.split('/').map(Number);
    const [num2, den2] = n.split('/').map(Number);

    // Calculate the product: (num1/den1) * (num2/den2) = (num1 * num2) / (den1 * den2)
    const numerator = num1 * num2;
    const denominator = den1 * den2;

