    const romanNumerals: Array<{ value: number; symbol: string }> = [
        { value: 1000, symbol: 'm' },
        { value: 900, symbol: 'cm' },
        { value: 500, symbol: 'd' },
        { value: 400, symbol: 'cd' },
        { value: 100, symbol: 'c' },
        { value: 90, symbol: 'xc' },
        { value: 50, symbol: 'l' },
        { value: 40, symbol: 'xl' },
        { value: 10, symbol: 'x' },
        { value: 9, symbol: 'ix' },
        { value: 5, symbol: 'v' },
        { value: 4, symbol: 'iv' },
        { value: 1, symbol: 'i' }
    ];

    let result = '';
    let remaining = number;

    for (const { value, symbol } of romanNumerals) {
        const count = Math.floor(remaining / value);
        if (count > 0) {
            result += symbol.repeat(count);
            remaining -= value * count;
        }
    }

    return result;
}
