function largest_divisor(n: number): number {
    if (n <= 1) {
        throw new Error("Input must be greater than 1");
    }

    // Start from n-1 and go down to 1
    // The first divisor we find will be the largest
    for (let i = n - 1; i >= 1; i--) {
        if (n % i === 0) {
            return i;
        }
    }

    // This should never happen for n > 1
    throw new Error("No divisor found");
}
