    // Check if the array is palindromic (balanced)
    const isBalanced = q.every((value, index) => value === q[q.length - 1 - index]);

    // Check if the sum of elements is less than or equal to maximum weight
    const sum = q.reduce((acc, val) => acc + val, 0);
