function solve(N: number): string {
    // Step 1: Calculate the sum of digits of N
    let digitSum = 0;
    let temp = N;
    while (temp > 0) {
        digitSum += temp % 10;
        temp = Math.floor(temp / 10);
    }

    // Step 2: Convert the digit sum to binary
    let binary = '';
    let num = digitSum;
    while (num > 0) {
        binary = (num % 2) + binary;
        num = Math.floor(num / 2);
    }

    // If digitSum is 0, binary should be "0"
    return binary || '0';
}
```

