function make_a_pile(n: number): number[] {
    const result: number[] = [];
    let currentStones = n;

    for (let i = 0; i < n; i++) {
        result.push(currentStones);
        // Determine the next number based on parity of n
        if (n % 2 === 1) {
            // n is odd: next odd number
            currentStones += 2;
        } else {
            // n is even: next even number
            currentStones += 2;
        }
    }

    return result;
}
