function unique_digits(x: number[]): number[] {
    const result: number[] = [];

    for (const num of x) {
        const digits = num.toString().split('').map(digit => parseInt(digit));
        const hasEvenDigit = digits.some(digit => digit % 2 === 0);
        if (!hasEvenDigit) {
            result.push(num);
        }
    }

    return result.sort((a, b) => a - b);
}
