```typescript
function count_nums(arr: number[]): number {
    let count = 0;
    for (const num of arr) {
        let digitSum = 0;
        const absNum = Math.abs(num);
        let temp = absNum;
        while (temp > 0) {
            digitSum += temp % 10;
            temp = Math.floor(temp / 10);
        }
        // For negative numbers, the first digit is negative
        if (num < 0) {
            digitSum = -digitSum;
        }
        if (digitSum > 0) {
            count++;
        }
    }
    return count;
}
```

