```typescript
function sort_array(arr: number[]): number[] {
  const countOnes = (n: number): number => {
    let count = 0;
    while (n > 0) {
      count += n & 1;
      n >>= 1;
    }
    return count;
  };

  return arr.sort((a, b) => {
    const onesA = countOnes(a);
    const onesB = countOnes(b);
    if (onesA !== onesB) {
      return onesA - onesB;
    }
    return a - b;
  });
}
```

