```typescript
function maximum(arr: number[], k: number): number[] {
    // Sort the array in ascending order
    const sortedArr = arr.sort((a, b) => a - b);

    // Extract the last k elements (the largest k numbers)
    const maxK = sortedArr.slice(-k);

    // Return the result sorted in ascending order
    return maxK.sort((a, b) => a - b);
}
