function prod_signs(arr: number[]): number | undefined {
  if (arr.length === 0) {
    return undefined;
  }

  const sumOfMagnitudes = arr.reduce((sum, num) => sum + Math.abs(num), 0);

  let productOfSigns = 1;
  for (const num of arr) {
    if (num > 0) {
      productOfSigns *= 1;
    } else if (num < 0) {
      productOfSigns *= -1;
    } else {
      productOfSigns *= 0;
      break;
    }
  }

  return sumOfMagnitudes * productOfSigns;
}
```

