```typescript
function is_nested(string: string): boolean {
  let depth = 0;
  let maxDepth = 0;

  for (const char of string) {
    if (char === '[') {
      depth++;
      maxDepth = Math.max(maxDepth, depth);
    } else if (char === ']') {
      depth--;
      if (depth < 0) return false; // Invalid bracket sequence
    }
  }

  // Check if the entire string is balanced
  if (depth !== 0) return false;

  // Return true if at least one bracket is nested (maxDepth > 1)
  return maxDepth > 1;
}
```

