function fix_spaces(text: string): string {
  // Remove leading and trailing spaces
  let cleaned = text.trim();

  // Replace multiple consecutive spaces with a single dash
  // First, replace sequences of 3 or more spaces with a single dash
  // Then, replace remaining single spaces with underscores
  const withDashes = cleaned.replace(/ {3,}/g, '-');
  const withUnderscores = withDashes.replace(/ /g, '_');

  return withUnderscores;
}
