assert.deepEqual(do_algebra(['+', '*', '-'], [2, 3, 4, 5]), 9); // 2 + 3 * 4 - 5 = 2 + 12 - 5 = 9
assert.deepEqual(do_algebra(['+', '-'], [1, 2, 3]), 0); // 1 + 2 - 3 = 0
assert.deepEqual(do_algebra(['*', '//'], [4, 2, 3]), 2); // 4 * 2 // 3 = 8 // 3 = 2
assert.deepEqual(do_algebra(['**'], [2, 3]), 8); // 2 ** 3 = 8
assert.deepEqual(do_algebra(['+', '+'], [1, 1, 1, 1]), 4); // 1 + 1 + 1 + 1 = 4
assert.deepEqual(do_algebra(['-', '*'], [10, 5, 2]), 0); // 10 - 5 * 2 = 10 - 10 = 0
